cd /tmp/phoebe-convo && python3 - <<'EOF'
import subprocess
total=0
for b in ['rachel','monica','phoebe','joey','chandler','ross']:
    out=subprocess.check_output(['git','log',f'origin/friend/{b}','--format=%B%x1e']).decode()
    for c in out.split('\x1e'):
        if 'Friend-Message: 1' in c and 'S07/E08' in c:
            total+=1
print('total S07/E08 friend messages:', total)
EOF

printf '#!/bin/sh
case "$1" in
 *Username*) echo x-access-token;;
 *Password*) echo "$GITHUB_TOKEN";;
esac
' > /tmp/askpass.sh && chmod +x /tmp/askpass.sh && echo ok
